public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.size() == 0) {
        return 0;
    }

    int maxLength = 0;
    for (String str : strings) {
        maxLength = Math.max(maxLength, isGood(str) || isGood(str.reverse().toString()) ? str.length() : 0);
    }
    return maxLength;
}

private boolean isGood(String str) {
    for (int i = 0; i < str.length(); i++) {
        String match = str.substring(i);
        if (strings.contains(match) || strings.contains(match.reverse().toString())) {
            return true;
        }
    }
    return false;
}

