private static void floodFill(char[][] grid, int row, int col) {
    // Mark the current cell as visited
    grid[row][col] = '.';
    // Explore adjacent cells (up, down, left, right)
    if (row > 0 && grid[row - 1][col] == '@') floodFill(grid, row - 1, col);
    if (row < grid.length - 1 && grid[row + 1][col] == '@') floodFill(grid, row + 1, col);
    if (col > 0 && grid[row][col - 1] == '@') floodFill(grid, row, col - 1);
    if (col < grid[row].length - 1 && grid[row][col + 1] == '@') floodFill(grid, row, col + 1);
}

