private static void dfs(char[][] grid, boolean[][] visited, int x, int y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || visited[x][y] || grid[x][y] != '@') {
        return;
    }
    visited[x][y] = true;
    dfs(grid, visited, x + 1, y);
    dfs(grid, visited, x - 1, y);
    dfs(grid, visited, x, y + 1);
    dfs(grid, visited, x, y - 1);
}

