public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if start and end coordinates are within the grid boundaries
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Check if start and end coordinates are equal
    if (Arrays.equals(start, end)) {
        return "can be travelled";
    }

    // Check if the path exists between start and end
    for (int[] path : paths) {
        if (Arrays.equals(path, new int[]{start[0], start[1], path[2], path[3]}) || 
            Arrays.equals(path, new int[]{start[0], start[1], path[3], path[2]})) {
            return "can be travelled";
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end points lie within the n-teresting space
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Check if the start and end points are directly adjacent
    if (Math.abs(start[0] - end[0]) + Math.abs(start[1] - end[1]) == 1) {
        return "can be travelled";
    }

    // Check if there are any direct paths between the start and end points
    for (int[] path : paths) {
        if (path[0] == start[0] && path[1] == start[1] && path[2] == end[0] && path[3] == end[1]) {
            return "can be travelled";
        }
        if (path[0] == end[0] && path[1] == end[1] && path[2] == start[0] && path[3] == start[1]) {
            return "can be travelled";
        }
    }

    // If none of the above conditions are met, travel is not possible
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();

    queue.offer(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        int x = current[0], y = current[1];
        int[] next;

        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        // Check up
        next = new int[]{x - 1, y};
        if (isValidPath(next, paths) && !visited[next[0]][next[1]]) {
            queue.offer(next);
            visited[next[0]][next[1]] = true;
        }

        // Check down
        next = new int[]{x + 1, y};
        if (isValidPath(next, paths) && !visited[next[0]][next[1]]) {
            queue.offer(next);
            visited[next[0]][next[1]] = true;
        }

        // Check left
        next = new int[]{x, y - 1};
        if (isValidPath(next, paths) && !visited[next[0]][next[1]]) {
            queue.offer(next);
            visited[next[0]][next[1]] = true;
        }

        // Check right
        next = new int[]{x, y + 1};
        if (isValidPath(next, paths) && !visited[next[0]][next[1]]) {
            queue.offer(next);
            visited[next[0]][next[1]] = true;
        }
    }

    return "cannot be travelled";
}

private static boolean isValidPath(int[] path, int[][] paths) {
    for (int[] p : paths) {
        if (p[0] == path[0] && p[1] == path[1]) {
            return true;
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a set to store visited cells
    Set<String> visited = new HashSet<>();
    visited.add(start[0] + "," + start[1]);

    // Perform a breadth-first search (BFS) to check if the end is reachable
    return bfs(n, start, end, paths, visited, "can be travelled");
}

private static String bfs(int n, int[] start, int[] end, int[][] paths, Set<String> visited, String result) {
    // Create a queue for BFS
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (Arrays.equals(current, end)) {
            return result;
        }

        // Explore all adjacent cells
        for (int[] path : paths) {
            int newX = current[0] + path[0];
            int newY = current[1] + path[1];

            if ( newX >= 0 && newX < n && newY >= 0 && newY < n &&
                !visited.contains(newX + "," + newY)) {
                visited.add(newX + "," + newY);
                queue.add(new int[]{newX, newY});
            }
        }
    }

    return "cannot be travelled";
}

