private static boolean dfs(int[] current,	boolean[] visited, int[][] paths) {
    if (visited[current[0]] == true && visited[current[1]] == true) {
        return true;
    }
    visited[current[0]] = visited[current[1]] = true;

    for (int[] path : paths) {
        if (path[0] == current[0] && path[1] == current[1]) {
            if (dfs(path, visited, paths)) {
                return true;
