public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int size = arr.length;
    int trimSize = (int) (size * 0.06); // Calculate 5%
    int[] trimmedArr = Arrays.copyOfRange(arr, trimSize + 1, size - trimSize - 1); // Remove the smallest and largest 5%
    int sum = 0;
    for (int num : trimmedArr) {
        sum += num;
    }
    double mean = (double) sum / trimmedArr.length;
    return mean;
}

