public boolean canArrange(int[] arr, int k) {
    for (int i = 0; i < arr.length / 2; i++) {
        if ((arr[i] % k + arr[arr.length / 2 + i] % k) % k != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int[] modFreq = new int[k]; // Array to count the frequency of each remainder when divided by k
    for (int num : arr) {
        modFreq[num % k]++; // Update the frequency of the current remainder
    }
    for (int i = 0; i <= k / 2; i++) { // Loop through the possible (offsets from 0 to k/2)
        if (modFreq[i] != modFreq[k - i]) { // Check if the frequencies are not equal
            return false; // Return false if not
        }
    }
    return true; // Return true if all frequencies are equal
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }
    int[] counts = new int[k];
    for (int num : arr) {
        counts[num % k]++;
    }
    // Check if the frequency of numbers with remainders k and k-1 is the same
    return counts[0] % 2 == 0 && Arrays.stream(counts).skip(1).allMatch(n -> n % 2 == 0);
}

public boolean canArrange(int[] arr, int k) {
    return arr.length % 2 == 0 && 
           arr.length / 2 == arr.length / (k == 0) ? 
           arr.length % 2 : 
           arr.length % (2 * k) == 0 ? 
           arr.length / (2 * k) : 
           false;
}

public boolean canArrange(int[] arr, int k) {
    // Initialize a counter for each possible remainder
    int[] remainders = new int[k];
    boolean result = true;

    // Count the remainders in the array
    for (int number : arr) {
        int remainder = number % k;
        remainders[remainder]++;
    }

    // Iterate over the remainders and check the constraints
    for (int remainder = 0; remainder < k; remainder++) {
        if (remainder == k / 2) {
            if (remainders[remainder] % 2 != 0) {
                result = false;
                break;
            }
        } else if (remainder != k / 2 && remainders[remainder] != remainders[k - remainder]) {
            result = false;
            break;
        }
    }

    return result;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> adj = new HashMap<>();
    for (int[] edge : edges) {
        adj.computeIfAbsent(edge[0], key -> new ArrayList<>()).add(edge[1]);
        adj.computeIfAbsent(edge[1], key -> new ArrayList<>()).add(edge[0]);
    }

    int totalTime = 0;
    findApples(0, -1, adj, hasApple, totalTime);
    return totalTime;
}

private boolean findApples(int node, int parent, Map<Integer, List<Integer>> adj, boolean[] hasApple, int totalTime) {
    for (int neighbor : adj.get(node)) {
        if (neighbor == parent) {
            continue;
        }
        if (findApples(neighbor, node, adj, hasApple, totalTime)) {
            totalTime += 2;
        }
    }
    return hasApple[node] || totalTime > 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> adjList = new HashMap<>();
    for (int[] edge : edges) {
        adjList.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
        adjList.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
    }
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n];
    visited[0] = true;
    queue.add(0);
    int time = 0;

    while (!queue.isEmpty()) {
        int currentNode = queue.poll();
        for (int neighbor : adjList.getOrDefault(currentNode, Collections.emptyList())) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                time +=2;
                queue.add(neighbor);
            } else if (hasApple[neighbor]) {
                time += 1;
            }
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    Set<Integer> visited = new HashSet<>();
    boolean apple = hasApple[0];

    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        if (!graph.containsKey(u)) graph.put(u, new ArrayList<>());
        if (!graph.containsKey(v)) graph.put(v, new ArrayList<>());
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    visited.add(0);
    return dfs(0, apple, graph);
}

private int dfs(int node, boolean apple, Map<Integer, List<Integer>> graph) {
    int time = 0;
    for (int neighbor : graph.get(node)) {
        if (visited.contains(neighbor)) continue;
        visited.add(neighbor);
        boolean subtreeApple = dfs(neighbor, apple, graph);
        if (subtreeApple || apple) {
            time += 2; // 2 edges for the subtree and back to the current node
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = buildGraph(n, edges);
    boolean[] visited = new boolean[n];

    int pathSum = dfs(0, graph, visited, hasApple);
    return pathSum;
}

private List<List<Integer>> buildGraph(int n, int[][] edges) {
    List<List<Integer>> graph = new ArrayList<>(n);
    for (int i = 0; i < n; ++i) {
        graph.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    return graph;
}

private int dfs(int cur, List<List<Integer>> graph, boolean[] visited, boolean[] hasApple) {
    if (visited[cur]) return 0;

    visited[cur] = true;
    int len = 0;

    for (int neighbor : graph.get(cur)) {
        len += dfs(neighbor, graph, visited, hasApple);
    }

    if (len > 0 || (hasApple[cur] && cur != 0)) {
        return len +1;
    } else {
        return 0;
    }
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Create directed graph using adjacency list
  ArrayList<Integer>[] adjList = new ArrayList[n];
  for (int i = 0; i < n; i++) {
    adjList[i] = new ArrayList<>();
  }
  for (int[] edge : edges) {
    adjList[edge[0]].add(edge[1]);
    adjList[edge[1]].add(edge[0]);
  }

  // Function to count apples reachable from a node
  int apples = countApples(adjList, hasApple, 0, -1); // Start from node 0 without parent node

  // Return the minimum time including the initial traversal and return at node 0
  return (apples == 0) ? 0 : apples * 2;
}

private int countApples(ArrayList<Integer>[] adjList, boolean[] hasApple, int currentNode, int parentNode) {
  int apples = 0;
  for (int neighbor : adjList[currentNode]) {
    if (neighbor != parentNode) {
      int currentApples = countApples(adjList, hasApple, neighbor, currentNode); // Recursively count apples in the subtree
      apples += currentApples; // Add current node's apple if counted
      if (currentApples > 0 || hasApple[neighbor]) { // Check if current node should be visited or has an apple
        continue; // Since parent node will return 1 always, avoid double return of 1
      }
      apples += 1; // Increment time if child node does not have an apple or parent 
    }
  }
  return apples;
}

public String sortString(String s) {
    char[] arr = s.toCharArray();
    Arrays.sort(arr, 0, arr.length);
    StringBuilder sb = new StringBuilder();
    int i = 0;
    int j = arr.length - 1;
    while (i <= j) {
        if (i == j) {
            sb.append(arr[i]);
            break;
        }
        sb.append(arr[i++]);
        sb.append(arr[j--]);
    }
    return sb.toString();
}

public String sortString(String s) {
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>(Comparator.reverseOrder());

    for (char c : s.toCharArray()) {
        if (Character.isLowerCase(c)) {
            minHeap.offer(c);
        } else {
            maxHeap.offer(c);
        }
    }

    StringBuilder result = new StringBuilder();
    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        if (!minHeap.isEmpty()) {
            result.append(minHeap.poll());
            if (minHeap.isEmpty()) {
                // If there are no more characters in the min heap, break to avoid infinite loop
                break;
            }
            if (Character.isLowerCase(minHeap.peek())) {
                // If the next character is lower case, add it to the min heap
                minHeap.offer(minHeap.poll());
            }
        }
        if (!maxHeap.isEmpty()) {
            result.append(maxHeap.poll());
            if (maxHeap.isEmpty()) {
                // If there are no more characters in the max heap, break to avoid infinite loop
                break;
            }
            if (Character.isLowerCase(maxHeap.peek())) {
                // If the next character is lower case, add it to the max heap
                maxHeap.offer(maxHeap.poll());
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
        List<Character> sortedChars = new ArrayList<>();
        Set<Character> uniqueChars = new HashSet<>();

        // Count occurrences of each character
        for (char c : s.toCharArray()) {
            uniqueChars.add(c);
        }
        for (char c : uniqueChars) {
            sortedChars.add(c);
        }

        // Sort characters based on their frequency
        sortedChars.sort((a, b) -> Integer.compare(s.chars().filter(c -> c == a).count(), s.chars().filter(c -> c == b).count()));

        StringBuilder result = new StringBuilder();
        int i = 0, j = sortedChars.size() - 1;

        // Alternate between picking smallest and largest characters
        while (result.length() < s.length()) {
            if (i < sortedChars.size()) {
                result.append(sortedChars.get(i));
                i++;
            }
            if (j >= 0) {
                result.append(sortedChars.get(j));
                j--;
            }
        }

        return result.toString();
    }

public String sortString(String s) {
    int[] chars = new int[26];
    for (char c : s.toCharArray()) {
        chars[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        for (int i = 0; i < 26; i++) {
            if (chars[i] > 0) {
                result.append((char) ('a' + i));
                chars[i]--;
            }
        }

        for (int i = 25; i >= 0; i--) {
            if (chars[i] > 0) {
                result.append((char) ('a' + i));
                chars[i]--;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    // Helper function to sort a character array
    char[] charArray = s.toCharArray();
    Arrays.sort(charArray);

    StringBuilder result = new StringBuilder();
    int start = 0;
    int end = charArray.length - 1;

    // Process the string in cycles of two or three
    while (start <= end) {
        // First cycle: pick smallest characters
        for (int i = start; i <= end; i++) {
            result.append(charArray[i]);
        }
        start += 2;

        // Second cycle: pick largest characters if first cycle is complete
        if (start <= end) {
            for (int i = end; i >= start; i--) {
                result.append(charArray[i]);
            }
        }
        end -= 2;
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int max = Arrays.stream(nums).sum();
    int n = nums.length, target = max % n == 0 ? max / n : max / n + 1;
    int prefixSum = 0;
    for (int i = 0; i < n; i++) {
        prefixSum += nums[i];
        if (prefixSum == target) return true;
        if (prefixSum < target) break;
        int remainingSum = max - prefixSum;
        if (i == 0 || i > 1 && nums[i - 2] * 2 != remainingSum) continue;
        if prefixSum <= remainingSum) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    double target = sum / (double) n;
    return check(nums, n, target);
}

private boolean check(int[] nums, int n, double target) {
    int count = 0;
    int maxCount = 0;
    int maxIndex = 0;
    for (int i = 0; i < n; i++) {
        if (nums[i] == target) {
            count++;
        }
    }
    if (count > 0) {
        return true;
    }
    int sum = 0;
    for (int i = 0; i < n; i++) {
        if (nums[i] != target) {
            sum += nums[i];
        }
        count++;
        if (count <= maxCount) {
            return false;
        }
        maxCount = count;
        maxIndex = i;
    }
    return sum == maxIndex * target;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = Arrays.stream(nums).sum();
    int n = nums.length;

    if (n < 2) return false;

    double avg = sum / n;
    if (avg != Math.floor(avg)) return false; // Average should be an integer

    for (int i = 1; i < n; i++) {
        sum -= nums[i];
        if (sum % i == 0 && sum / i == avg) {
            return true;
        }
        sum += nums[i];
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    if (totalSum == 0) {
        return false; // If total sum is zero, it's impossible to split the array evenly.
    }
    int requiredAverage = totalSum / (int) Math.ceil(nums.length / 2.0);
    boolean[] dp = new boolean[requiredAverage + 1];
    dp[0] = true; // Base case: an array of size 0 can be split into two arrays with the same average (empty both).

    for (int num : nums) {
        for (int s = requiredAverage; s >= num; s--) {
            dp[s] = dp[s] || dp[s - num];
        }
    }

    return dp[requiredAverage];
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    // Calculate the total sum of the array
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // Iterate through possible split points
    for (int i = 1; i <= nums.length / 2; i++) {
        double sum1 = 0, sum2 = 0;
        // Calculate the sum of the first half of the array
        for (int j = 0; j < i; j++) {
            sum1 += nums[j];
        }
        // Calculate the corresponding sum for the second half
        for (int j = i; j < nums.length; j++) {
            sum2 += nums[j];
        }

        // Check if the averages are equal
        if (sum1 * 2 == totalSum && sum1 != 0) {
            return true;
        }
    }

    // If no valid split point is found, return false
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 2) {
        return Math.min(cost[0], cost[1]);
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost.length <= 1) {
        return cost.length == 0 ? 0 : cost[0];
    }

    int dp[] = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < dp.length; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
    }

    return Math.min(dp[dp.length-1], dp[dp.length-2]);
}

