public int minOperations(int n) {
    int totalSum = 0;
    for (int i = 0; i < n; i++) {
        totalSum += (2 * i) + 1;
    }
    int targetSum = totalSum / n;
    int operations = 0;
    while (targetSum != totalSum) {
        for (int i = 0; i < n; i++) {
            if (totalSum == targetSum) {
                return operations;
            }
            if ((2 * i) + 1 + operations == targetSum) {
                totalSum += operations;
                targetSum += 1;
                operations = 0;
                break;
            }
        }
        operations++;
    }
    return operations;
}

public int minOperations(int n) {
    int totalOperations = 0;
    for (int i = 0; i < n / 2; i++) {
        totalOperations += n - 2 * i;
    }
    if (n % 2 != 0) { // If n is odd, one more operation is required
        totalOperations += n - 2 * (n / 2);
    }
    return totalOperations;
}

public int minOperations(int n) {
        int result = 0;
        int midValue = n / 2;

        for (int i = 0; i <= n / 2; i++) {
            int leftValue = (2 * i) + 1;
            int rightValue = (2 * i + 1) + 1;

            if (leftValue != midValue && rightValue == midValue) {
                result += n - leftValue;
            } else if (leftValue == midValue && rightValue != midValue) {
                result += leftValue;
            } else {
                result += Math.abs(leftValue - rightValue);
            }
        }

        return result;
    }

