    if (n <= 1) {
        return n;
    }
    return n + (n - 1) / 2;
}

public int minOperations(int n) {
    int operations = 0;
    for (int i = 0; i < n / 2 && n % 2 != i % 2; i++) {
        operations += Math.abs(n - 2 * i - 1);
    }
    return operations;
}

