public int findMinFibonacciNumbers(int k) {
    int a = 1, b = 1, c, i = 0;
    while (b < k) {
        c = a + b;
        a = b;
        b = c;
        i++;
    }
    c = a + b;
    if (c == k) {
        return i;
    }
    return findMinFibonacciNumbers(k - c) + 1;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fib = new ArrayList<>();
    int fib1 = 1, fib2 = 1;
    fib.add(fib1);
    fib.add(fib2);

    while (fib.get(fib.size()-1) < k) {
        fib.add(fib.get(fib.size()-1) + fib.get(fib.size()-2));
    }

    int count = 0;
    while (k > 0) {
        while (fib.get(fib.size()-1) > k) {
            fib.remove(fib.size()-1);
        }
        count++;
        k -= fib.get(fib.size()-1);
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;

    while (a + b <= k) {
        fibs.add(a + b);
        int temp = a;
        a = b;
        b = temp + b;
    }

    int ans = 0;
    for (int i = fibs.size() - 1; i >= 0 && k > 0; i--) {
        if (k >= fibs.get(i)) {
            k -= fibs.get(i);
            ans++;
        }
    }

    return ans;
}

public int findMinFibonacciNumbers(int k) {
    int[] dp = new int[k + 1];
    LinkedList<Integer> chain = new LinkedList<>();
    int i = 0;

    dp[0] = dp[1] = 1;
    while (dp[i] <= k) i++;

    for (int j = 2; j <= i; j++) {
        dp[j] = dp[j - 1] + dp[j - 2];
        chain.addLast(dp[j]);
    }

    int count = 0;
    while (k > 0) {
        count++;
        k -= chain.get(chain.size() - 1);
    }

    return count;
}

