    int[] seen = new int[26]; // Array to keep track of seen characters

    for (int i = 0; i < length; i++) {
        int currentMaxUnique = 0;
        int nextStart = i;

        while (nextStart < length && s.charAt(nextStart) != 'A') { // Skip sequences of 'A's
            if (seen[s.charAt(nextStart) - 'a'] == 0) {
                seen[s.charAt(nextStart) - 'a'] = 1;
                nextStart++;
                currentMaxUnique++;
            } else {
                break;
            }
        }

        maxUnique = Math.max(maxUnique, currentMaxUnique);
    }

    return maxUnique;
}

public int maxUniqueSplit(String s)
{
