public int maxUniqueSplit(String s) {
    int splitCount = 1;
    int startIndex = 0;
    Set<String> uniqueSubstrings = new HashSet<>();

    while (startIndex < s.length()) {
        int endIndex = startIndex + 1;
        while (endIndex <= s.length() && !uniqueSubstrings.contains(s.substring(startIndex, endIndex))) {
            endIndex++;
        }
        uniqueSubstrings.add(s.substring(startIndex, endIndex));
        splitCount++;
        startIndex = endIndex;
    }

    return splitCount;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) return 0;

    int len = s.length();
    int[][] dp = new int[len][len]; // dp[i][j] represents the max number of unique substrings for s[i:j]
    boolean[][] visited = new boolean[len][len]; // visited[i][j] indicates if s[i:j] has been visited by a substring split

    for (int i = 0; i < len; i++) {
        dp[i][i] = 1; // A single character is considered a unique substring
    }

    for (int size = 2; size <= len; size++) {
        for (int i = 0; i <= len - size; i++) {
            int j = i + size - 1;
            if (i == j) {
                dp[i][j] = 1; // If the size is 1, it's a unique substring
            } else {
                dp[i][j] = 0;
                for (int mid = i; mid < j; mid++) {
                    if (visited[i][mid] || visited[mid + 1][j]) {
                        continue; // Skip if a substring split has already been visited
                    }
                    if (s.substring(i, mid + 1).equals(s.substring(mid + 1, j + 1))) {
                        dp[i][j] = Math.max(dp[i][j], dp[i][mid] + dp[mid + 1][j]);
                    }
                }
            }
            visited[i][j] = true;
        }
    }

    return dp[0][len - 1];
}

