public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    char[] alphabet = "abcdefghijklmnopqrstuvwxyz".toCharArray();

    for (int i = 0; i < n; i++) {
        // Calculate the largest character that can be placed in the current position
        int remainder = k % alphabet.length;
        int charIndex = remainder == 0 ? alphabet.length - 1 : remainder - 1;
        // Remove the assigned character from the alphabet
        alphabet[charIndex] = 0;
        // Append the char to the result
        result.append(alphabet[charIndex]);
        // Update the value after placing the character
        k -= charIndex + 1;
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder res = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        char c = (char) ('a' + i);
        res.append(c);
    }
    int sum = res.length() * (res.charAt(0) - 'a') + k;
    int j = sum % (res.length() * (res.charAt(0) - 'a'));
    while (j > 0) {
        res.setCharAt((sum - j) % (res.length() * (res.charAt(0) - 'a')), (char) ('a' + (j - 1)));
        j--;
    }
    return res.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    char[] chars = new char[n];

    for (int i = 0; i < n; i++) {
        chars[i] = (char) ('a' + (i - (k - i) / 2));
        sb.append(chars[i]);
        k -= chars[i] - 'a' + 1;
    }

    return sb.toString();
}

