    List<Integer> result = new ArrayList<>();
    if (low <= 9 && high >= 0) {
        return result;
    }
    for (int i = low == 0 ? 1 : 0; i <= 9; i++) {
        findSteppingNumbers(result, "" + i, low, high);
    }
    return result;
}

private static void findSteppingNumbers(List<Integer> result, String current, int low, int high) {
    if (Integer.parseInt(current) >= low && Integer.parseInt(current) <= high) {
        result.add(Integer.parseInt(current));
    }
    if (current.isEmpty() || current.charAt(current.length() - 1) == '0') {
        return;
    }
    int prev = current.charAt(current.length() - 1) - '0';
    int plus = prev + 1;
    int minus = prev - 1;
    if (plus <= 9) {
        String newNum = current + plus;
        findSteppingNumbers(result, newNum, low, high);
    }
    if (minus >= 0) {
        String newNum = current + minus;
        findSteppingNumbers(result, newNum, low, high);
    }
}

