       steps.add(i);
        visited[i] = true;
    }

    // Process all numbers from 2 to high
    for (int num = 2; num <= high; num++) {
        int lastDigit = num % 10;
        // Extend the steps by adding one more or one less to the last digit
        if (lastDigit != 0 && !visited[lastDigit - 1]) {
            steps.add(num * 10 + lastDigit - 1);
            visited[lastDigit - 1] = true;
        }
        if (lastDigit != 9 && !visited[lastDigit + 1]) {
            steps.add(num * 10 + lastDigit + 1);
            visited[lastDigit + 1] = true;
        }
    }
    // Sort the steps list and return
    steps.sort(Integer::compare);
    return steps;
}

