public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][1 << n];
    Arrays.fill(dp, -1);
    return count(A, 0, 0, dp);
}

private static int count(int[] A, int mask, int pot, int[][] dp) {
    if (mask == (1 << n) - 1) return 1;
    if (dp[mask][pot] != -1) return dp[mask][pot];
    int ways = 0;
    for (int i = 0; i < n; i++) {
        if ((mask & (1 << i)) == 0 && A[i] * A[i] + pot * pot == (i == 0 ? 0 : A[i - 1] * A[i - 1])) {
            ways += count(A, mask | (1 << i), i, dp);
        }
    }
    return dp[mask][pot] = ways;
}

public static int squarePermutations(int[] A) {
        int n = A.length;
        if (n % 2 != 0) {
            return 0;
        }

        // Create a map to store the number of occurrences of each element
        Map<Integer, Integer> count = new HashMap<>();
        for (int num : A) {
            count.put(num, count.getOrDefault(num, 0) + 1);
        }

        // Find the element with the maximum frequency, which will be at the center (0th index) in the square permutation
        int center = -1;
        for (int k : count.keySet()) {
            if (count.get(k) >= count.get(center)) {
                center = k;
            }
        }

        // Create a boolean array to keep track of used elements in the permutation
        boolean[] used = new boolean[n];

        // Recursively generate the square permutation
        return backtrack(count, used, 0, center);
    }

private static int backtrack(Map<Integer, Integer> count, boolean[] used, int start, int center) {
        int n = count.size();
        int totalPermutations = 1;

        // If we have filled half the array, check if the remaining elements can form a valid square permutation
        if (n == start) {
            return isSquarePermutation(used) ? 1 : 0;
        }

        // Recursively generate permutations with the center element
        for (int i = 0; i < n; i++) {
            if (count.get(A[i]) == 0 || used[i]) {
                continue;
            }
            used[i] = true;
            count.put(A[i], count.get(A[i]) - 1);
            totalPermutations += backtrack(count, used, start + 1, center);
            used[i] = false;
            count.put(A[i], count.get(A[i]) + 1);
        }

        return totalPermutations;
    }

private static boolean isSquarePermutation(boolean[] used) {
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            int sum = used[i] ? A[i] + i : 0;
            int diff = used[j] ? -(A[j] + i) : A[j] - i;
            if (sum != diff && sum != 0 && diff != 0) {
                return false;
            }
        }
        return true;
    }

public static int squarePermutations(int[] A) {
    int[] seen = new int[10]; // Map to keep track of seen numbers
    int[] count = new int[10]; // Array to count permutation lengths
    int result = 0;

    // Base case: if the array has only one element
    if (A.length == 1) {
        seen[A[0]] = 1;
        count[A[0]] = 1;
        return seen[A[0]];
    }

    // Iterate through each element in the array
    for (int i = 0; i < A.length; i++) {
        int num = A[i];
        // If the number has been seen before, continue to the next iteration
        if (seen[num] > 0) continue;

        // Mark the number as seen and update the count
        seen[num] = 1;
        count[A[i]]++;

        // Recursively generate permutations for the remaining elements
        result += generatePermutations(num, count, new HashSet<>());

        // Restore the count (backtrack)
        count[A[i]]--;
    }

    return result;
}

private static int generatePermutations(int num, int[] count, Set<Integer> used) {
    int result = 0;

    // If there are no more elements to permute, return 1
    if (count[num] == 0) return 1;

    for (int i = 0; i < count[num]; i++) {
        if (!used.contains(i)) {
            used.add(i);
            result += generatePermutations(num, count, used);
            used.remove(i);
        }
    }

    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n < 2) {
        return 1; // A empty array or a single element is always a square permutation.
    }

    Map<Integer, Set<Integer>> map = new HashMap<>();
    Set<Integer> visited = new HashSet<>();

    // Seed the map with the first element and its square.
    int first = A[0];
    map.put(first, new HashSet<Integer>());
    map.get(first).add(getSquare(first));

    for (int i = 1; i < n; i++) {
        int current = A[i];
        int currentSquare = getSquare(current);

        // Add the current number to the map if the square is not in it already.
        if (!map.containsKey(currentSquare)) {
            map.put(currentSquare, new HashSet<Integer>());
        }

        // Check all previous numbers to see if they can form a square permutation pair.
        for (int prev : map.get(first)) {
            if (isPerfectSquare(current + prev)) {
                map.get(currentSquare).add(current);
                map.get(currentSquare).add(prev);
                visited.add(prev);
            }
        }

        // Move to the next previous number.
        visited.add(first);
        first = current;
    }

    int count = 0;
    // Count the number of valid square permutations.
    for (int square : map.keySet()) {
        count += map.get(square).size();
    }

    return count;
}

private static int getSquare(int n) {
    return n * n;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];
    Stack<Integer> stack = new Stack<>();

    // Find the smallest index to the left of each element
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        leftSmaller[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(i);
    }

    stack.clear();

    // Find the smallest index to the right of each element
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        rightSmaller[i] = stack.isEmpty() ? heights.length : stack.peek();
        stack.push(i);
    }

    // Calculate the area of each rectangle
    for (int i = 0; i < heights.length; i++) {
        maxArea = Math.max(maxArea, (rightSmaller[i] - leftSmaller[i] - 1) * heights[i]);
    }

    return maxArea;
}

