    if (rows == 0) return new int[0];

    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    // Traverse in both positive and negative diagonals
    for (int diag = 0; diag < rows + cols - 1; diag++) {
        // Determine the direction (positive or negative) based on the diagonal
        if (diag < cols) {
            // Positive diagonal (to the right)
            int i = 0, j = diag;
            while (i < rows && j < cols) {
                result[index++] = mat[i++][j++];
            }
        } else {
            // Negative diagonal (down)
            int i = diag - cols + 1, j = cols - 1;
            while (i < rows && j >= 0) {
                result[index++] = mat[i++][j--];
            }
        }
    }

    return result;
}

