}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 1;
    while (i > 0 && digits[i] <= digits[i - 1]) {
        i--;
    }
    if (i == 0) {
        return -1; // n is already the smallest possible number
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i - 1]) {
        j--;
    }
    char temp = digits[i - 1];
    digits[i - 1] = digits[j];
    digits[j] = temp;

    Arrays.sort(digits, i, digits.length);
    return Integer.parseInt(new String(digits));
}

public static int findSmallestInteger(int n) {
    int[] sortedDigits = new int[9];
    int count = 0;
    int index = 0;

    // Count the occurrences of each digit
    while (n > 0) {
        int digit = n % 10;
        sortedDigits[digit]++;
        n /= 10;
        if (sortedDigits[digit] == 1) count++;
        if (count > 1) {
            // If a digit's count > 1, it cannot be the smallest possible number
            return -1;
        }
        index = Math.max(index, digit);
    }
    if (index == 0) return -1; // If all digits are 0, no smaller number can be formed

    // Prepare the smallest number by placing the smaller values first
    int smallestNumber = 0;
    while (sortedDigits[index] > 0) {
        smallestNumber = smallestNumber * 10 + index;
        sortedDigits[index]--;
    }

    // Add the higher values to the smallest number
    for (int i = 0; i < 10; i++) {
        if (i == index) continue; // Skip the already placed digit
        for (int j = 0; j < sortedDigits[i]; j++) {
            smallestNumber = smallestNumber * 10 + i;
        }
    }

    return smallestNumber;
}

public static int findSmallestInteger(int n) {
    String numStr = Integer.toString(n);
    int[] digits = new int[numStr.length()];

    // Convert the integer to characters and store them in an array
    for (char c : numStr.toCharArray()) {
        digits[i++] = c - '0';
    }

    // Sort the digits in ascending order
    Arrays.sort(digits);

    // Find the first position where digits can be swapped to get a smaller number than n
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit to the right of i that is greater than digits[i]
            for (int j = digits.length - 1; j > i; j--) {
                if (digits[j] > digits[i]) {
                    // Swap digits[i] and digits[j]
                    int temp = digits[i];
                    digits[i] = digits[j];
                    digits[j] = temp;
                    // Sort the rest of the array
                    Arrays.sort(digits, i + 1, digits.length);
                    break;
                }
            }
            // Convert the array of digits back to an integer
            int result = 0;
            for (int d : digits) {
                result = result * 10 + d;
            }
            return result;
        }
    }

    // Return -1 if no such rearrangement exists
    return -1;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    for (int i = 0; i < digits.length; i++) {
        for (int j = i + 1; j < digits.length; j++) {
            if (digits[j] < digits[i]) {
                // Swap digits
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
                // Try to find the smallest integer with the digits
                for (int k = 0; k < digits.length - 1; k++) {
                    for (int l = k + 1; l < digits.length; l++) {
                        if (digits[l] < digits[k]) {
                            // Swap digits
