public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;
    int i = 0, j = 0, k = 0;
    int[] dp = new int[n];
    dp[0] = 1;

    for (int i = 1; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], Math.min(dp[j] * 2, dp[k] * 3));
        if (dp[i] == dp[j] * 2) j++;
        if (dp[i] == dp[k] * 3) k++;
    }
    return dp[n - 1];
}

