public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int energy = 0;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            energy = Math.max(energy, currentEnergy);
            currentEnergy = 1;
        }
    }

    // For the last character
    energy = Math.max(energy, currentEnergy);

    return energy;
}

