public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    helper(result, 0, 0, n);
    return result;
}

private static void helper(List<Integer> result, int index, int left, int n) {
    if (index > n || index > left) return; // Stop if index exceeds n or is greater than the part left to be filled

    result.add(index);

    int right = index * 10 + 1;
    for (int i = 0; i < 10; i++) {
        helper(result, right + i, left, n);
    }
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        LinkedList<Integer> queue = new LinkedList<>();
        queue.offer(1);
        while (!queue.isEmpty()) {
            int current = queue.poll();
            result.add(current);
            if (current * 10 <= n) {
                queue.offer(current * 10);
            }
            if (current % 10 != 9 && current + 1 <= n) {
                queue.offer(current + 1);
            }
        }
        return result;
    }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 0; i <= 9; i++) {
        visit(i, result, n);
    }
    return result;
}

private static void visit(int i, List<Integer> result, int n) {
    if (i <= n) {
        result.add(i);
        if (i * 10 <= n) {
            for (int j = 0; j <= 9; j++) {
                visit(i * 10 + j, result, n);
            }
        }
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        helper(result, i, n);
    }
    return result;
}

private static void helper(List<Integer> result, int current, int upperLimit) {
    result.add(current);
    if (current * 10 <= upperLimit) {
        for (int i = 0; i <= 9 && current * 10 + i <= upperLimit; i++) {
            helper(result, current * 10 + i, upperLimit);
        }
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    dfs(result, 0, n);
    return result;
}

private static void dfs(List<Integer> result, int current, int upperLimit) {
    if (current > upperLimit) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        dfs(result, current * 10 + i, upperLimit);
    }
}

