public static int minPerfectSquareSum(int n) {
    if (n == 0) return 0;
    int(dp[] = new int[n + 1];
    for (int i = 1; i <= n; ++i) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; ++j)
            dp[i] = Math.min(dp[i], 1 + dp[i - j * j]);
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) return -1; // Return -1 if n is negative

    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0; // Base case: no perfect square needed to sum up to 0

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= Math.sqrt(i); j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

